function pageDesc(){if(route==='dashboard/tasks')return '集中查看复查、预约和日常待办。';return ({visit:'把每次就诊、检查与后续安排，放在一起。',exercise:'记录每一次动起来，也留意身体的感受。',meal:'用简单的记录，慢慢看见自己的饮食习惯。',metric:'沿着时间看变化，每个数值都有自己的来处。',task:'把想做的事情，变成每天可完成的小步骤。',file:'让报告与资料有处可寻，随时为就诊做好准备。',settings:'管理你的健康空间、资料与连接。',day:'按天查看饮食、锻炼和饮水，随时补记。',library:'就诊、运动、饮食、监测与原始资料。',mine:'管理工作台、个人设置与数据空间。'})[page]||''}
function stats(){const latest=t=>latestHealthRecord(items,'metric',today,t);const w=latest('weight'),p=latest('pressure'),s=latest('sleep');const mins=byKind('exercise').filter(x=>x.date===today).reduce((n,x)=>n+x.duration,0);return [{label:'最近体重',value:w?.value??'—',unit:w?'kg':'',ic:'scale',sub:w?`${healthRecordDate(w,today)} · ${healthRecordStatus(w,today)}`:'等待第一条记录',type:'weight'},{label:'今日运动',value:mins,unit:'分钟',ic:'exercise',sub:mins?'今天已记录':'今天还没有运动记录',type:'exercise'},{label:'最近睡眠',value:s?.value??'—',unit:s?'小时':'',ic:'moon',sub:s?`${healthRecordDate(s,today)} · ${healthRecordStatus(s,today)}`:'等待第一条记录',type:'sleep'},{label:'最近血压',value:p?`${p.value}/${p.secondary}`:'—',unit:p?'mmHg':'',ic:'heart',sub:p?`${healthRecordDate(p,today)} · ${healthRecordStatus(p,today)}`:'等待第一条记录',type:'pressure'}].map((s,i)=>`<article class="metric-card"><div class="metric-top">${s.label}<span class="metric-icon">${icon(s.ic,16)}</span></div><div class="metric-value">${s.value}<small>${s.unit}</small></div><div class="metric-bottom">${icon('clock',10)}${esc(s.sub)}</div>${space==='demo'&&i!==1?`<svg class="spark" viewBox="0 0 90 32" fill="none"><path d="M2 20 13 18 24 23 35 12 46 16 57 10 68 15 79 8 89 11" stroke="${['#88a66c','#be9b76','#a0aac1','#c69b8e'][i]}" stroke-width="1.5"/></svg>`:''}</article>`).join('')}
function trendCard(){return `<section class="card"><div class="card-head"><h2 class="card-title">监测趋势</h2><select id="trend-range" class="range-control" aria-label="趋势时间范围"><option value="7" ${range===7?'selected':''}>近 7 天</option><option value="14" ${range===14?'selected':''}>近 14 天</option><option value="30" ${range===30?'selected':''}>近 30 天</option></select></div><div class="tabs">${['weight','pressure','sleep','glucose','heart','steps'].map(t=>`<button class="tab ${metricType===t?'active':''}" data-action="trend:${t}">${metricNames[t]}</button>`).join('')}</div>${chart()}<div class="chart-note"><span class="legend"><i></i>${metricNames[metricType]} · ${units[metricType]}${metricType==='pressure'?' · 实线收缩压 / 虚线舒张压':''}</span><span>仅展示记录，不作诊断判断</span></div></section>`}
function chart(){const cutoff=new Date(today+'T12:00:00Z');cutoff.setUTCDate(cutoff.getUTCDate()-range+1);const minDate=cutoff.toISOString().slice(0,10);const data=byKind('metric').filter(x=>x.type===metricType&&x.date>=minDate&&x.date<=today).sort((a,b)=>(a.date+(a.time||'')).localeCompare(b.date+(b.time||'')));if(!data.length){const last=latestHealthRecord(items,'metric',today,metricType);if(last)return `<div class="health-trend-fallback"><p>近 ${range} 天暂无${metricNames[metricType]}记录</p><strong>最近一次：${esc(last.value)}${last.secondary?'/'+esc(last.secondary):''} ${esc(last.unit||units[metricType])}</strong><time datetime="${esc(last.date)}">${esc(healthRecordDate(last,today))}</time></div>`;return `<div class="empty" style="padding:44px 20px">${icon('activity',28)}<p>还没有${metricNames[metricType]}记录</p>${btn('记录一次','add:metric','','plus')}</div>`;}
 const values=data.flatMap(d=>metricType==='pressure'?[d.value,d.secondary]:[d.value]);const pad=Math.max((Math.max(...values)-Math.min(...values))*.4,metricType==='weight'?.5:1);const lo=Math.max(0,Math.min(...values)-pad),hi=Math.max(...values)+pad;const W=520,H=165,x=i=>45+(data.length===1?215:i*440/(data.length-1)),y=v=>15+112*(1-(v-lo)/(hi-lo));const line=key=>data.map((d,i)=>`${i?'L':'M'}${x(i).toFixed(1)} ${y(d[key]).toFixed(1)}`).join(' ');
 return `<div class="chart"><svg viewBox="0 0 ${W} ${H}" role="img" aria-label="${metricNames[metricType]}历史趋势，共${data.length}条记录">${[0,1,2,3].map(i=>{const v=hi-i*(hi-lo)/3,yy=y(v);return `<line x1="45" y1="${yy}" x2="500" y2="${yy}" stroke="#edf1e6" stroke-dasharray="3 4"/><text x="33" y="${yy+3}" text-anchor="end" fill="#a3ae97" font-size="9">${v.toFixed(metricType==='weight'||metricType==='sleep'||metricType==='glucose'?1:0)}</text>`}).join('')}<path d="${line('value')}" stroke="var(--theme-ink)" stroke-width="2" fill="none"/>${metricType==='pressure'?`<path d="${line('secondary')}" stroke="#b89471" stroke-width="2" stroke-dasharray="4 4" fill="none"/>`:''}${data.map((d,i)=>`<circle cx="${x(i)}" cy="${y(d.value)}" r="3" fill="white" stroke="var(--theme-ink)" stroke-width="1.6"><title>${d.date} ${d.value}${d.secondary?'/'+d.secondary:''} ${d.unit}</title></circle>`).join('')}${[0,Math.floor((data.length-1)/2),data.length-1].filter((v,i,a)=>a.indexOf(v)===i).map(i=>`<text x="${x(i)}" y="151" fill="#a0ad91" font-size="9" text-anchor="middle">${fmtDate(data[i].date)}</text>`).join('')}</svg></div>`}
function taskRows(a,upcoming=false){return a.map(t=>`<div class="task-row ${t.done?'done':''}"><button class="check ${t.done?'checked':''}" data-action="toggle:${t.id}" aria-label="${t.done?'取消完成':'完成'}：${esc(t.title)}" aria-pressed="${t.done}">${t.done?icon('check',12):''}</button><div class="task-copy"><strong>${esc(t.title)}</strong><small>${esc(t.time||'当天')} · ${upcoming?(t.date===today?'今天':esc(t.date))+(t.date<today?' · 已逾期':''):dateLabel(t.date)}</small></div><span class="pill ${catClass(t.category)}">${esc(t.category||'日常')}</span><button class="icon-btn" data-action="edit:${t.id}" aria-label="编辑${esc(t.title)}">${icon('edit',13)}</button></div>`).join('')}
function dashboard(){
 const pending=byKind('task').filter(x=>!x.done).sort((a,b)=>a.date.localeCompare(b.date)||(a.time||'').localeCompare(b.time||''));const tasks=pending.slice(0,layoutUI.options('tasks').limit||5);
 const latest=type=>latestHealthRecord(items,'metric',today,type),reading=latest(metricType),lastExercise=latestHealthRecord(items,'exercise',today),report=latestHealthRecord(items,['report','file'],today);
 const cutoff=new Date(today+'T12:00:00Z');cutoff.setUTCDate(cutoff.getUTCDate()-6);const startDate=cutoff.toISOString().slice(0,10);
 const exercise=byKind('exercise').filter(x=>x.date>=startDate&&x.date<=today),minutes=exercise.reduce((n,x)=>n+Number(x.duration||0),0);
 const days=Array.from({length:7},(_,i)=>{const d=new Date(cutoff);d.setUTCDate(d.getUTCDate()+i);const date=d.toISOString().slice(0,10);return {date,minutes:exercise.filter(x=>x.date===date).reduce((n,x)=>n+Number(x.duration||0),0)};}),maxMinutes=Math.max(1,...days.map(x=>x.minutes));
 const meal=latestHealthRecord(items,'meal',today),visit=latestHealthRecord(items,'visit',today),meals=meal?[meal]:[],visits=visit?[visit]:[];
 const water=byKind('water').filter(x=>x.date===today),waterMl=water.reduce((n,x)=>n+Number(x.volume||0),0),waterGoal=Number(settings.waterGoalMl)||2000,waterPercent=Math.min(100,Math.max(0,Math.round(waterMl/waterGoal*100)));
 const medications=byKind('medication').filter(x=>x.status==='进行中'&&x.date<=today&&(!x.endDate||x.endDate>=today));
 const action=(label,name,ic='')=>`<button class="btn" data-action="${name}">${ic?icon(ic,18):''}${label}</button>`;
 const blank=(text,name,label)=>`<div class="health-empty"><p>${text}</p>${action(label,name,'plus')}</div>`;
 const trend=trendCard().replace('class="card"','class="card health-trend"').replace('<div class="tabs">',`<div class="health-trend-reading"><span>${reading?`${esc(reading.value)}${reading.secondary?'/'+esc(reading.secondary):''}`:'—'}<small>${esc(reading?.unit||units[metricType])}</small></span><p>${reading?`${esc(healthRecordDate(reading,today))} · ${healthRecordStatus(reading,today)}`:'还没有'+metricNames[metricType]+'记录'}</p></div><div class="tabs">`);
 return `<div class="health-overview"><div class="health-overview-heading"><h1>健康总览</h1><div class="health-quick-actions" aria-label="快捷记录">${action('记一餐','add:meal','meal')}${action('记运动','add:exercise','exercise')}${action('记数值','add:metric','metric')}${action('传报告','qc-open:file','file')}</div></div><div class="health-bento"><div class="health-primary"><div class="health-monitoring">${trend}<section class="health-body-metrics" aria-label="最近身体指标">${['weight','sleep','heart'].map(type=>{const m=latest(type);return `<button class="health-body-metric" data-action="trend:${type}"><span class="health-metric-symbol">${icon(({weight:'scale',sleep:'moon',heart:'heart'})[type],23)}</span><span class="health-metric-copy"><span>${metricNames[type]}</span><b>${m?esc(m.value):'—'}<small>${m?esc(m.unit):''}</small></b><time>${m?esc(healthRecordDate(m,today)):'尚未记录'}</time>${m?`<small class="health-record-status">${healthRecordStatus(m,today)}</small>`:''}</span>${icon('arrow',15)}</button>`;}).join('')}</section></div><div class="health-lower-grid"><section class="card health-exercise"><div class="card-head"><h2 class="card-title">近 7 天运动</h2><button class="text-btn" data-action="nav:exercise">运动记录 ${icon('arrow',12)}</button></div><div class="health-exercise-total"><b>${minutes}</b><span>分钟</span><small>${exercise.length} 次已记录的运动</small></div><div class="health-exercise-bars" role="img" aria-label="近7天运动时长，${days.map(x=>x.date+' '+x.minutes+'分钟').join('，')}">${days.map(d=>`<div class="health-exercise-day"><span>${d.minutes||''}</span><div><i style="height:${d.minutes/maxMinutes*100}%"></i></div><time>${d.date===today?'今天':d.date.slice(5).replace('-','/')}</time></div>`).join('')}</div>${lastExercise?`<article class="health-latest-exercise"><div><h3>最近一次运动</h3><time datetime="${esc(lastExercise.date)}${lastExercise.time?'T'+esc(lastExercise.time):''}">${esc(healthRecordDate(lastExercise,today))}</time><p>${esc(lastExercise.title||lastExercise.type||'运动')} · ${esc(lastExercise.duration)} 分钟</p><small class="health-record-status">${healthRecordStatus(lastExercise,today)}</small></div><button class="icon-btn" data-action="edit:${lastExercise.id}" aria-label="查看或编辑${esc(lastExercise.title)}">${icon('arrow',15)}</button></article>`:blank('还没有运动记录。','add:exercise','记运动')}</section><section class="card health-meals"><div class="card-head"><h2 class="card-title">最近饮食</h2><button class="text-btn" data-action="nav:meal">全部 ${icon('arrow',12)}</button></div><div class="health-compact-list">${meals.length?meals.map(x=>`<article class="health-meal-row"><span class="health-meal-symbol">${icon('meal',27)}</span><div><h3>${esc(x.mealType||'餐食')} <time datetime="${esc(x.date)}${x.time?'T'+esc(x.time):''}">${esc(healthRecordDate(x,today))}</time></h3><p>${esc(x.title)}</p>${x.portion?`<small>${esc(x.portion)}</small>`:''}${aiTag(x)}<small class="health-record-status">${healthRecordStatus(x,today)}</small></div><button class="icon-btn" data-action="edit:${x.id}" aria-label="查看或编辑${esc(x.title)}">${icon('arrow',15)}</button></article>`).join(''):blank('还没有餐食记录。','add:meal','记一餐')}</div></section></div></div><aside class="health-secondary">${captureUI.stepsCard()}<section class="card health-water"><div class="card-head"><h2 class="card-title">饮水</h2><button class="icon-btn" data-action="nav:day" aria-label="查看饮水明细">${icon('info',17)}</button></div><div class="health-water-content"><div class="health-water-ring" style="--water-progress:${waterPercent}%" role="img" aria-label="今日饮水${waterMl}毫升，记录目标${waterGoal}毫升，进度${waterPercent}%"><div><b>${waterMl}</b><span>/ ${waterGoal} ml</span></div></div><div class="health-water-actions">${action('记一次饮水','daily-water','plus')}<small>${water.length?`今天已记录 ${water.length} 次`:'今天还没有饮水记录'}</small><button class="text-btn" data-action="nav:settings">调整记录目标</button></div></div></section><section class="card health-tasks"><div class="card-head"><div><h2 class="card-title">近期待办</h2><p>${pending.length} 项未完成</p></div><button class="icon-btn" data-action="add:task" aria-label="添加待办">${icon('plus',17)}</button></div><div class="task-list">${tasks.length?taskRows(tasks,true):blank('安排一件接下来要做的事。','add:task','添加待办')}</div>${pending.length>tasks.length?`<p class="health-task-overflow">仅显示最近 ${tasks.length} 项</p>`:''}<button class="health-all-tasks" data-action="nav:dashboard/tasks">查看全部待办 ${icon('arrow',13)}</button></section><section class="card health-visits"><div class="card-head"><h2 class="card-title">最近就诊</h2><button class="text-btn" data-action="nav:visit">全部 ${icon('arrow',12)}</button></div><div class="health-compact-list">${visits.length?visits.map(x=>`<button class="health-visit-row" data-action="med-open:${x.id}">${institutionMark(x,{esc,icon})}<span><b>${esc(x.title)}</b><small>${esc(healthRecordDate(x,today))} · ${esc(x.hospital||x.department||'机构待补充')}</small><small class="health-record-status">${healthRecordStatus(x,today)}</small></span>${icon('arrow',15)}</button>`).join(''):blank('还没有保存就诊记录。','add:visit','添加就诊')}</div></section><section class="card health-reports"><div class="card-head"><h2 class="card-title">最近报告与资料</h2><button class="text-btn" data-action="med-view:reports">全部 ${icon('arrow',12)}</button></div><div class="health-compact-list">${report?`<button class="health-visit-row" data-action="${report.kind==='report'?'med-report':'med-preview'}:${report.id}"><span class="health-metric-symbol">${icon('file',23)}</span><span><b>${esc(report.title)}</b><small>${esc(healthRecordDate(report,today))}${report.kind==='report'?' · 报告文字':' · 原件'}</small><small class="health-record-status">${healthRecordStatus(report,today)}</small></span>${icon('arrow',15)}</button>`:blank('还没有报告或资料。','qc-open:file','上传资料')}</div></section></aside></div><details class="health-medication-summary"><summary><span>${icon('heart',18)}今日用药 <small>${medications.length?`${medications.length} 个进行中的方案`:'暂无进行中的方案'}</small></span><span>展开查看 ${icon('arrow',13)}</span></summary>${medical.todayCard()||`<div class="health-empty"><p>按原处方录入用药方案，再记录实际服用情况。</p><button class="text-btn" data-action="med-view:medications">用药管理 ${icon('arrow',12)}</button></div>`}</details></div>`;
}
function detail(x){if(x.kind==='metric')return `${metricNames[x.type]} · ${x.value}${x.secondary?'/'+x.secondary:''} ${x.unit}${x.note?' · '+x.note:''}`;if(x.kind==='exercise')return `${x.type||'运动'} · ${x.duration} 分钟`;if(x.kind==='visit')return `${x.hospital||'机构待补充'} · ${x.city||'城市待补充'} · ${x.department||'未填写科室'} · ${x.status}`;if(x.kind==='meal')return `${x.mealType||'餐食'}`;if(x.kind==='water')return `${x.volume} ml`;return x.note||''}
function fileReportAction(x){const report=byKind('report').find(r=>r.fileId===x.id);if(!report&&x.fileCategory!=='报告待整理'&&!(route==='visit/inbox'))return '';return `<button class="text-btn" data-action="${report?'med-report:'+report.id:'qc-organize:'+x.id}">${report?'查看就诊报告':'整理为就诊报告'} ${icon('arrow',11)}</button>`;}
function fileIsLinked(x){return Boolean(x.visitId||byKind('report').some(r=>r.fileId===x.id)||byKind('medication').some(m=>m.imageFileId===x.id)||byKind('meal').some(m=>(m.attachmentIds||[]).includes(x.id)));}
const listKind=()=>route==='dashboard/tasks'?'task':page;
function taskOverview(){return `<button class="text-btn medical-back" data-action="nav:dashboard">← 返回今天</button>${listPage('task')}`;}
function filtered(kind=listKind()){return sorted(byKind(kind).filter(x=>{
 const matchesText=!query||`${x.title} ${x.note} ${x.hospital||''} ${x.rawText||''}`.toLowerCase().includes(query.toLowerCase());
 const matchesDate=!filterDate||x.date===filterDate;
 const matchesStatus=filterStatus==='all'||(kind==='task'?(filterStatus==='done')===x.done:kind==='file'?(filterStatus==='linked')===fileIsLinked(x):x.status===filterStatus);
 return matchesText&&matchesDate&&matchesStatus;
}));}
