 if(kind==='file')fields=`${!id?'<label class="upload-box">'+icon('file',29)+'<p>选择要保存的报告或资料</p><small>PDF / PNG / JPG / WEBP / TXT · 最大 10 MB</small><input type="file" name="upload" id="file-upload" accept=".pdf,.png,.jpg,.jpeg,.webp,.txt" required aria-label="选择资料文件"></label><div style="height:18px"></div>':''}`+select('关联就诊记录（可选）','visitId',[['','暂不关联'],...byKind('visit').map(v=>[v.id,`${v.date} ${v.title}`]),...(x.visitId&&!items.some(i=>i.id===x.visitId)?[[x.visitId,'原就诊已移除（保留关联）']]:[])],x.visitId||'');
 const kindSelect=!id&&kind!=='file'?select('记录类型','recordKind',Object.entries(names).filter(([k])=>k!=='file'),kind):'';
